import{_ as i,l as o,o as e,c as l,v as t,p as d,x as r,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"栈式对寄存器式 VM","description":"","frontmatter":{"title":"栈式对寄存器式 VM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-vs-register-vm.md","filePath":"cs/stack-vs-register-vm.md","lastUpdated":1789023840000}'),h={name:"cs/stack-vs-register-vm.md"};function m(_,a,E,u,T,v){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="栈式对寄存器式-vm" tabindex="-1">栈式对寄存器式 VM <a class="header-anchor" href="#栈式对寄存器式-vm" aria-label="Permalink to &quot;栈式对寄存器式 VM&quot;">​</a></h1><div class="epigraph"><p>栈式用隐式栈顶当操作数，编码短；寄存器式把操作数编号写进指令，少压栈，利于映射到真实寄存器与 JIT。</p><footer>—— 据 Shi et al., Virtual Machine Showdown；Davis et al., The Case for Virtual Register Machines；Java vs LuaJIT/Dalvik 对照整理</footer></div><p>上一课<a href="/cs/bytecode-interpreter">字节码解释器</a> 未钉操作数形态。缺口是 <strong>stack vs register</strong>：JVM 典型栈式；Lua 5、Dalvik 寄存器式。本课钉编码与分派成本，线程化下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>栈式：<code>iadd</code> 无操作数字段。编译简单（表达式 SDT 自然）。执行：多次 push/pop，解释器内存流量大。寄存器式：<code>add r1,r2,r3</code>，编译要做一次「虚拟寄存器分配」（可简化）。缺口是<strong>这笔税</strong>，不是 GC。</p><p>Showdown 论文：寄存器式解释往往少指令数，但指令更大。</p><h3 id="虚拟寄存器不是物理寄存器" tabindex="-1">虚拟寄存器不是物理寄存器 <a class="header-anchor" href="#虚拟寄存器不是物理寄存器" aria-label="Permalink to &quot;虚拟寄存器不是物理寄存器&quot;">​</a></h3><p>VM 寄存器是解释器数组槽。JIT 再映射到硬件。不要把 Dalvik <code>v0</code> 当 <code>x0</code>。</p><p><span class="marginnote">Shi, Gregg, Beatty, Ertl。Davis 等。本课不把 WebAssembly 的操作数栈当已讲完，后课 wasm 再接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>栈式生成：后序遍历。寄存器式：把 SSA 名或栈槽编号写进指令。局部变量：JVM 用局部表+栈；寄存器 VM 把局部直接当寄存器。</p>',11)),(e(),d(p,null,{default:r(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXPR%5B%22%E8%A1%A8%E8%BE%BE%E5%BC%8F%22%5D%20--%3E%20STK%5B%22%E5%8E%8B%E6%A0%88%E8%BF%90%E7%AE%97%22%5D%0A%20%20EXPR%20--%3E%20REG%5B%22%E4%B8%89%E5%9C%B0%E5%9D%80%E5%AD%97%E8%8A%82%E7%A0%81%22%5D%0A%20%20STK%20--%3E%20INT%5B%22%E8%A7%A3%E9%87%8A%22%5D%0A%20%20REG%20--%3E%20INT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 SSA：寄存器 VM 更接近中端 IR，JIT 少一层 lowering。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调用约定：栈式把参数压栈；寄存器式规定窗口或移动。异常与 GC 根：栈式要精确栈深度图；寄存器式要 live 寄存器位图。</p><p>不要混用两种编码当「优化开关」而不改生成器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写线程化。后课默认：两种编码都是合法字节码。下一课线程化分派：减 switch 开销。</p><p>也不把寄存器 VM 当 GPU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>栈式编码密、解释器栈操作多；寄存器式指令少、编译稍复杂。</li><li>JIT 路径上寄存器式更近 SSA。</li><li>根枚举方式随编码变。</li><li>出处：Shi et al.；Davis et al.；对照 JVM 规范、Lua。</li></ul>',9))])}const f=i(h,[["render",m]]);export{S as __pageData,f as default};
